// src/settings/sections/llmSettings.ts
function createLLMSettings(containerEl, plugin, display) {
  new import_obsidian13.Setting(containerEl).setName("AI Provider").setDesc(
    "Choose which provider settings to edit. This dropdown will also select your default provider, which can be overridden at the node level using config arrows."
  ).addDropdown((dropdown) => {
    var _a7;
    dropdown.addOption("openai", "OpenAI");
    dropdown.addOption("azure_openai", "Azure OpenAI");
    dropdown.addOption("ollama", "Ollama");
    dropdown.addOption("gemini", "Gemini");
    dropdown.addOption("anthropic", "Anthropic");
    dropdown.addOption("groq", "Groq");
    dropdown.setValue(
      (_a7 = plugin.settings.llmProvider) != null ? _a7 : DEFAULT_SETTINGS.llmProvider
    );
    dropdown.onChange(async (value) => {
      plugin.settings.llmProvider = value;
      await plugin.saveSettings();
      display();
    });
  });
  new import_obsidian13.Setting(containerEl).setName("LLM call concurrency limit (pLimit)").setDesc(
    "The maximum number of LLM calls that can be made at once. Decrease this if you are running into rate limiting issues."
  ).addText(
    (text) => text.setValue(
      Number.isInteger(plugin.settings.pLimit) ? plugin.settings.pLimit.toString() : DEFAULT_SETTINGS.pLimit.toString()
    ).onChange(async (value) => {
      if (!isNaN(parseInt(value)) && parseInt(value) > 0) {
        plugin.settings.pLimit = parseInt(value);
        await plugin.saveSettings();
      } else {
        plugin.settings.pLimit = DEFAULT_SETTINGS.pLimit;
        await plugin.saveSettings();
      }
    })
  );
  new import_obsidian13.Setting(containerEl).setName("Enable Vision").setDesc(
    "Enable vision for LLM calls. This will allow the LLM to see images embedded with markdown embedding syntax (e.g. ![[image.png]] or ![description](image-link.com)). This setting can be overridden at the node level using a 'enableVision' config arrow with the value 'true' or 'false'."
  ).addToggle((toggle) => {
    toggle.setValue(plugin.settings.enableVision);
    toggle.onChange(async (value) => {
      plugin.settings.enableVision = value;
      await plugin.saveSettings();
      display();
    });
  });
  containerEl.createEl("h1", { text: "LLM" });
  if (plugin.settings.llmProvider === "openai") {
    createOpenAISettings(containerEl, plugin);
  } else if (plugin.settings.llmProvider === "azure_openai") {
    createAzureOpenAISettings(containerEl, plugin);
  } else if (plugin.settings.llmProvider === "ollama") {
    createOllamaSettings(containerEl, plugin);
  } else if (plugin.settings.llmProvider === "gemini") {
    createGeminiSettings(containerEl, plugin);
  } else if (plugin.settings.llmProvider === "anthropic") {
    createAnthropicSettings(containerEl, plugin, display);
  } else if (plugin.settings.llmProvider === "groq") {
    createGroqSettings(containerEl, plugin);
  }
}

